\begin{tabular}{|p{2.6cm}|p{4.0cm}|p{4.0cm}|p{4.0cm}|}
\hline
\textbf{Mạch kiến thức} & \textbf{Đề ôn tập số 1} & \textbf{Đề ôn tập số 2} & \textbf{Đề ôn tập số 3} \\ \hline
Phép tính \& Phân tích nhân tử (1,5đ) & Ia: $(2x-3)(x+1) - 2x(x-2)$; Ib: $x^2-6x+9-y^2$ & Ia: $(15x^3y^2-10x^2y+5xy):5xy$; Ib: Tìm x $(x-3)^2-x(x+2)=11$ & Ia: Rút gọn HĐT $(x+2)^2+(x-2)^2-2(x^2-1)$; Ib: $x^3-2x^2+x-xy^2$ \\ \hline
Phân thức đại số (2,0đ) & ĐKXĐ, rút gọn $A = \frac{3x}{x-2}$, tính tại $x=-5$, tìm x nguyên & Tính $A$, rút gọn $B = \frac{x}{x+1}$, tìm x nguyên lớn nhất & Rút gọn $A = \frac{10}{x^2-4}$, nhân $P = A \cdot B = \frac{x-2}{x+2}$, tìm x nguyên \\ \hline
Thống kê \& Toán thực tế (1,0đ) & Biểu đồ cột kép CLB Toán học, tính tỉ lệ \% nữ & Đo khoảng cách hai bờ hồ dùng đường trung bình tam giác & Biểu đồ đoạn thẳng áo ấm từ thiện, tỉ lệ tăng trưởng \\ \hline
Hình học tổng hợp (3,0đ) & Tam giác vuông, HCN, hình thang cân, hình thoi & Tam giác vuông, HCN, trung trực, vuông góc $AM \perp DE$ & Tam giác vuông, HCN, hình thoi $AMCK$, góc vuông $\widehat{DHE}=90^\circ$ \\ \hline
VDC Cực trị \& BĐT (0,5đ) & Min hai biến $M = x^2-4xy+5y^2+10x-22y+28$ & PT nghiệm thực $(x+y-1)^2+(y-2)^2=0$, tính $P=(x+y)^{2024}$ & HĐT ba biến $x+y+z=0$, tính $P = \sum \frac{xy}{x^2+y^2-z^2}$ \\ \hline
\end{tabular}\end{center}

